class Counter
{
    protected int count;
    public virtual void Add() => count++;
    public virtual void AddMany(int n) { for (var i = 0; i < n; i++) Add(); }
}
class AuditedCounter : Counter
{
    public int Calls;
    public override void Add() { Calls++; base.Add(); }
    public override void AddMany(int n) { Calls += n; base.AddMany(n); }
}

var c = new AuditedCounter();
c.AddMany(3);
Console.WriteLine(c.Calls);
